import{_ as t,o as a,c as o,ah as l}from"./chunks/framework.BO5fCcdb.js";const p=JSON.parse('{"title":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400）","description":"","frontmatter":{"date":"2026-11-10T00:00:00.000Z","title":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400）","summary":"Anthropic 于 2026-11-09 发布 Claude Fable 5.2（claude-fable-5-2）。默认 1M 上下文、12.8 万输出上限，输入/输出单价降到 $8 / $40（每百万 token），可选 fast mode。多数日常任务官方仍建议先用 Opus 5.5；从 5.1 切过来有 4 处改动要先看，其中 3 处会直接 400。","category":"新闻简报","verified":"2026-11-12T00:00:00.000Z","tags":["新闻简报","AI 工具","模型"],"sources":[{"url":"https://www.anthropic.com/claude-fable-and-mythos-5-2","author":"Anthropic","platform":"Official"},{"url":"https://platform.claude.com/docs/en/models/fable-5-2/whats-new-fable-5-2","author":"Claude Platform Docs","platform":"Docs"},{"url":"https://platform.claude.com/docs/en/models/fable-5-2/overview","author":"Claude Platform Docs","platform":"Docs"}],"wordCount":1039,"readingTime":3,"freshness":{"items":[{"kind":"content","label":"内容更新","date":"2026-11-13","title":"页面文件最近一次提交的日期（git，UTC+8）"},{"kind":"checked","label":"核查","date":"2026-11-12","title":"按官方来源逐条重新核对的日期；与发布日期、内容修改日期分开记"}]},"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400） | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"Anthropic 于 2026-11-09 发布 Claude Fable 5.2（claude-fable-5-2）。默认 1M 上下文、12.8 万输出上限，输入/输出单价降到 $8 / $40（每百万 token），可选 fast mode。多数日常任务官方仍建议先用 Opus 5.5；从 5.1 切过来有 4 处改动要先看，其中 3 处会直接 400。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-11-10-claude-fable-5-2"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-11-10-claude-fable-5-2-67b17934c7.png"}],["meta",{"property":"og:image:alt","content":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400） · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400） | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"Anthropic 于 2026-11-09 发布 Claude Fable 5.2（claude-fable-5-2）。默认 1M 上下文、12.8 万输出上限，输入/输出单价降到 $8 / $40（每百万 token），可选 fast mode。多数日常任务官方仍建议先用 Opus 5.5；从 5.1 切过来有 4 处改动要先看，其中 3 处会直接 400。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-11-10-claude-fable-5-2-67b17934c7.png"}],["meta",{"name":"twitter:image:alt","content":"Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400） · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-11-10-claude-fable-5-2"}]]},"headers":[],"relativePath":"daily/2026-11-10-claude-fable-5-2.md","filePath":"daily/2026-11-10-claude-fable-5-2.md","lastUpdated":1794527875000}'),r={name:"daily/2026-11-10-claude-fable-5-2.md"};function n(d,e,c,i,s,u){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="claude-fable-5-2-上线-输入-8-输出-40-长程-agent-用-从-5-1-切过去前先看-4-处改动-3-处会直接-400" tabindex="-1">Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400） <a class="header-anchor" href="#claude-fable-5-2-上线-输入-8-输出-40-长程-agent-用-从-5-1-切过去前先看-4-处改动-3-处会直接-400" aria-label="Permalink to &quot;Claude Fable 5.2 上线：输入 $8 / 输出 $40，长程 Agent 用；从 5.1 切过去前先看 4 处改动（3 处会直接 400）&quot;">​</a></h1><h2 id="发生了什么" tabindex="-1">发生了什么 <a class="header-anchor" href="#发生了什么" aria-label="Permalink to &quot;发生了什么&quot;">​</a></h2><p>Anthropic 在 <strong>2026-11-09</strong> 发布 <strong>Claude Fable 5.2</strong>（API 模型 ID：<code>claude-fable-5-2</code>），面向要求高的推理和长时间 Agent 任务。同日还有 <strong>Claude Mythos 5.2</strong>（<code>claude-mythos-5-2</code>），能力相同，但只开放给通过 Anthropic 核验项目（如 Cyber Verification Program）的组织。</p><p>以上日期与规格来自官方公告和 Claude Platform 文档，<strong>不是我们实测</strong>。本站上线日为 <strong>2026-11-10</strong>。</p><p>官方原文：</p><blockquote><p>Developers can get started with <code>claude-fable-5-2</code> on the Claude Platform.</p></blockquote><h2 id="新变化-能干什么" tabindex="-1">新变化 / 能干什么 <a class="header-anchor" href="#新变化-能干什么" aria-label="Permalink to &quot;新变化 / 能干什么&quot;">​</a></h2><ul><li><strong>默认 100 万 token 上下文</strong>（也是上限），单次最多 <strong>12.8 万</strong> 输出 token；自适应思考一直开着，用 <code>effort</code> 控制深度，API 默认 <code>high</code></li><li><strong>单价低于 5.1</strong>：输入 <strong>$8</strong> / 输出 <strong>$40</strong>（每百万 token）。5.1 是 $10 / $50。缓存读取 <strong>$0.20</strong>；5 分钟缓存写入 $10，1 小时缓存写入 $16；Batch 为 $4 / $20（官方便宜一半）</li><li><strong>可选 fast mode</strong>：官方写输出速度最高约 2.5 倍，价格是 <strong>$16 / $80</strong>。在 Claude API 的 Messages 请求里设 <code>speed: &quot;fast&quot;</code>，不必加 beta 头；Microsoft Foundry（Anthropic 托管）上是单独模型 ID <code>claude-fable-5-2-fast</code></li><li>可用平台包括：Claude API、Amazon Bedrock（<code>global.anthropic.claude-fable-5-2</code> 或 <code>us.anthropic.claude-fable-5-2</code>，只在 <code>bedrock-runtime</code> 端点）、AWS 上的 Claude Platform、Google Cloud（Anthropic 托管 / Google 托管）、Microsoft Foundry</li><li>官方建议：多数写代码和知识工作先用 <strong>Claude Opus 5.5</strong>；评测仍不够再用 Fable 5.2</li></ul><h2 id="适用条件" tabindex="-1">适用条件 <a class="header-anchor" href="#适用条件" aria-label="Permalink to &quot;适用条件&quot;">​</a></h2><ul><li>Fable 5.2：Claude API 上对客户开放（合作云见各平台文档）</li><li>Mythos 5.2：须通过核验项目，或联系客户团队</li><li>消费端：公告只写「符合条件的订阅套餐」。Claude 定价页（2026-11-12 核对）写的是 Max、Ultra 含 Fable，最高占每周额度的一半；Pro 写的是 Fable 用 usage credits 结算。各套餐能不能用、怎么算，以定价页当天为准</li><li>公告还写：上线当周（限时活动），符合条件的订阅套餐会有额外 Fable 用量（含 Fable 的套餐/席位按订阅时长给 1–3 次 Fable 重置；Pro 与 Team 标准席位的周限额里，Fable 最高可占到 50%）。以公告原文为准，活动是否仍有效请打开公告页核对</li></ul><h2 id="限制-坑-从-5-1-切过来尤其要看" tabindex="-1">限制 / 坑（从 5.1 切过来尤其要看） <a class="header-anchor" href="#限制-坑-从-5-1-切过来尤其要看" aria-label="Permalink to &quot;限制 / 坑（从 5.1 切过来尤其要看）&quot;">​</a></h2><p>官方列出 4 处可能让旧代码出问题的改动，其中 1、3、4 会直接返回 <strong>400</strong>，第 2 条只是悄悄丢掉推理、请求仍然成功：</p><ol><li><strong>前缀检查对所有账号生效</strong>：如果你改了 <code>system</code>、<code>tools</code> 或更早的消息，又把 5.2 的 thinking 块送回去，会 400。5.1 默认只对 2026-08-31 及之后新建的账号这样报错</li><li><strong>5.2 的 thinking 块只有 Fable 5.2 / Mythos 5.2 能读</strong>；切回 Opus 5.5 或 Fable 5.1 时，这些推理会被丢掉（请求仍会成功）</li><li><strong>计算机操作</strong>须用 <code>computer_toolset_20260801</code>；继续声明旧的 <code>computer_20251124</code> 会 400（Amazon Bedrock 除外）</li><li><strong>advisor 工具</strong>（beta）：执行模型如果是 Fable 5.2 / Mythos 5.2，顾问也只能是这两个之一</li></ol><p>另外（官方，不是实测）：</p><ul><li>不能关思考；<code>thinking</code> 设成 disabled 或带 <code>budget_tokens</code> 的手动延长思考会 400</li><li>强制调用工具（<code>tool_choice</code> 为 <code>any</code> 或指定某个 tool）会 400</li><li>官方写明省略 <code>temperature</code>、<code>top_p</code>、<code>top_k</code>（具体哪些取值会 400，见官方文档的 Sampling parameters 一节）</li><li><strong>须保留 30 天数据</strong>；除非 Anthropic 另行授权，否则不能走零保留（ZDR）。不满足会 400</li><li>不支持 Priority Tier</li><li>可靠知识截止日期为 <strong>2026-06</strong></li><li>文档写承诺下线不早于 <strong>2027-11-09</strong></li><li>Fable 对高风险网络安全和多数生物学研究任务有安全分类器拦截；这类任务官方导向 Mythos 核验通道</li></ul><p>切模型前对照：<a href="https://platform.claude.com/docs/en/models/fable-5-2/whats-new-fable-5-2" target="_blank" rel="noopener noreferrer">What’s new</a> 和 <a href="https://platform.claude.com/docs/en/models/fable-5-2/migration-guide" target="_blank" rel="noopener noreferrer">迁移指南</a>。</p><p>公告：<a href="https://www.anthropic.com/claude-fable-and-mythos-5-2" target="_blank" rel="noopener noreferrer">https://www.anthropic.com/claude-fable-and-mythos-5-2</a></p><p>WANGXXXL 首次核实于 2026-11-10 UTC+8；2026-11-12 对照官方公告、模型文档、迁移指南和定价页重新核对，更正了标题里的报错数量（3 处 400、1 处静默丢弃推理）、Bedrock 模型 ID 和订阅套餐的说法。</p>',18)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
